import {S,term as T,step as P,check as Q,task as A,lesson as L} from './shared.js';
export default [
L(2,1,{
 title:'文字怎样进入模型：编号、向量和形状',summary:'把一句短句逐步变成数字数组，再看模型参数和输入长度为什么不是同一回事。',prerequisites:['w1-l1'],
 terms:[T('token','分词器选定的编码单位，可以是字符、子词或字节；并不固定等于一个汉字。','教学例子先把“我爱琴”拆成三个字符。'),T('tokenizer 分词器','规定文字怎样变成编号，以及怎样从编号还原文字的程序。','词表规定“琴”对应 2；模型和分词器必须同意这个编号。'),T('embedding 嵌入','用可学习的查找表，把离散编号转换成一组数。','编号 2 查到 [0.2,0.8]；不是把 2 当成语言中的大小。'),T('tensor 张量与 shape 形状','本课可先理解成有维度信息的数值数组；shape 告诉你各轴有多长。','两个句子、每句三个位置、每个位置四个数，形状为 [2,3,4]。')],
 sections:[P('第 1 步：先约定编码，不要让模型猜编号','定义词表“我→0、爱→1、琴→2”。把“我爱琴”转成 [0,1,2]。这个过程是编码规则，不是通过梯度训练得到预测。真实分词器处理未知词和子词的方式更复杂，本例只用于看清接口。','若保存权重后又把“我”和“琴”的编号交换，数组形状仍然合法，但模型读到的含义变了。因此分词器和权重需要一起保存。'),P('第 2 步：编号通过一张表变成向量','设表有三行，每行两个数：[1,0]、[0,1]、[0.2,0.8]。输入 [0,1,2] 就选择对应三行。每行这些数都是可以被训练修改的参数，初始值未必有明确语义。','embedding 不是数据库里固定写好的词义，也不能仅凭某个维度说它就是“情绪”。本课的关键是查表操作与参数归属；语义要通过训练和评测产生。'),P('第 3 步：用形状检查每一步','常用符号 B 表示一次放入的样本数，T 表示每个样本的位置数，D 表示每个位置的表示长度，V 表示词表大小。输入编号是 [B,T]，查表后是 [B,T,D]；查找表自身的形状是 [V,D]。','V=3、D=2 时查表只有 6 个参数。把句子从 3 个位置变成 30 个位置，使用这张表的次数更多，但这张表仍只有 6 个参数。中间计算占用的内存可以增加，参数量不一定增加。'),P('第 4 步：补齐和顺序是另外两个问题','多个句子长短不同，可用专门的 PAD 编号补齐；PAD 是凑形状用的，不是句子里的真实内容。后面要分别处理它是否能被注意力读取、是否参与损失。','“我爱琴”和“琴爱我”使用相同的三个词，但顺序不同。模型必须获得位置信息。最直观的方法是给每个位置加一个向量；RoPE 是另一种把位置作用在注意力查询和键上的方式，本课只识别其职责，不要求推导。')],
 worked:{title:'从 3 个编号到 3×2 的数组',steps:['词表规定三个 token，共 V=3。','输入“我爱琴”变成 [0,1,2]，T=3。','每个编号取出长度 D=2 的一行，得到 [[1,0],[0,1],[0.2,0.8]]。','增加输入长度会增加取出的行数，不会自动增加表里的行数。'],takeaway:'先分清数据的形状与参数的形状，再讨论模型大小。'},
 example:{code:'vocab = {"我": 0, "爱": 1, "琴": 2}\ntable = [[1, 0], [0, 1], [0.2, 0.8]]\nids = [vocab[c] for c in "我爱琴"]\nvectors = [table[i] for i in ids]\nprint(ids)\nprint(vectors)\nprint("parameters", sum(len(row) for row in table))',output:'[0, 1, 2]\n[[1, 0], [0, 1], [0.2, 0.8]]\nparameters 6',explanation:'这里查表使用普通列表；实际训练一般使用 PyTorch 的 Embedding 模块，才能方便地计算并更新表中参数。'},
 checks:[Q('输入长度翻倍，embedding 参数一定翻倍吗？','比较 [B,T,D] 与 [V,D] 哪个轴改变。','不一定。只改变 T，V 和 D 不变时，查找表参数仍为 V×D；中间表示会变大。',2),Q('换一套编号但保留旧权重，为什么可能预测错误？','查看编号到底选择表中的哪一行。','同一个数字会查到旧含义对应的参数，输入与权重的语义不再匹配。',0)],
 practice:{title:'做一次编码往返和形状检查',steps:[A('给词表增加一个新字符，再增加对应向量行。','词表有 4 项、每行 2 个数时共有 8 个参数。','只增加词表编号却没加表行，会产生越界。'),A('把输入改成“琴爱我”，观察向量行顺序。','使用的是同一组参数，只是取出的顺序改变。','顺序变化不是重新训练。'),A('自己写反向字典，把编号还原成文字。','原始文本与还原文本相同。','出现未知字符时要明确报错或设计 UNK，不能默默替换为别的字。')]},sources:[S.hf,S.transformer]
}),
L(2,2,{
 title:'Attention：当前位置怎样读取其他位置',summary:'先用三个分数算一次加权平均，再逐步理解 Q、K、V 和因果遮挡。',prerequisites:['w2-l1'],
 terms:[T('Attention 注意力','根据当前查询与各位置的匹配程度，对那些位置的信息做加权汇总。','不是只挑一个词，而是用多个权重汇总信息。'),T('Q、K、V','Query 是查询，Key 是供匹配的索引，Value 是被读取的内容；通常来自可训练的线性投影。','像用查询找目录，再读取内容；这个比喻不意味着模型真的有文字目录。'),T('softmax','把一组分数转换成总和为 1 的非负权重。','较大的分数通常得到较大的权重，但不一定独占全部权重。'),T('causal mask 因果掩码','规定每个位置只能读取当前位置及之前输入的可见性规则。','第 2 个位置不能读取第 3 个输入中的答案。')],
 sections:[P('第 1 步：从加权平均建立直觉','先假设三个位置存储的值是 [10,20,100]，权重是 [0.5,0.5,0]。汇总结果为 0.5×10+0.5×20+0×100=15。Attention 的最后一步就是这种加权汇总，只是实际的值通常是向量。','权重不是永远固定的：当前要解决的问题不同，分数也会不同。网络会学习怎样产生查询 Q 和键 K，让它们的匹配分数有助于任务。'),P('第 2 步：用 Q 与 K 计算分数','若查询 q=[1,0]，三个键为 [1,0]、[0,1]、[1,1]，点积得到 [1,0,1]。点积只是对应数字相乘后相加。标准缩放点积注意力还除以每个头的键维度 d 的平方根，再做 softmax。','V 可以与 K 不同：K 负责匹配，V 负责提供内容。多头注意力让多个独立投影分别做这种计算，然后合并。不要把“头数”代入缩放公式里的 d。'),P('第 3 步：把不该看的位置真正排除','当第 2 个位置只能看前两个位置时，第三个分数必须在 softmax 前被屏蔽。常见加性掩码给允许位置加 0，给禁止位置加负无穷；指数化后禁止位置的权重为 0。','浮点 0/1 并不表示禁止/允许：如果它被直接加到分数上，1 只是把分数加大。不同接口的布尔掩码也有不同约定；例如 Transformer 的 True 表示屏蔽，而 scaled_dot_product_attention 的布尔 True 表示允许。先查实际调用的 API。'),P('第 4 步：用实验检查信息是否泄漏','把未来输入值 100 改成 10000。正确遮挡下，当前输出应仍为 15。若变化了，说明未来信息通过某条路径影响了当前输出，需要检查掩码和网络信息流。','真实网络测试时先关闭随机 dropout，否则两次输出差异可能来自随机性。dropout 是训练时随机丢弃部分中间值的机制，本周先知道比较两次前向时要固定这种随机条件。')],
 worked:{title:'未来内容变了，当前结果应该不变',steps:['我们站在第 2 个位置，只允许读取第 1、2 个位置。','给前三个位置的未缩放示例分数为 [0,0,2]，遮挡后为 [0,0,−∞]。','softmax 后权重为 [0.5,0.5,0]。','读取值 [10,20,100] 得到 15；最后一个值无论改成什么都不应改变结果。'],takeaway:'因果性是可验证的信息约束，不只是变量名里写了 causal。'},
 example:{code:'import math\nscores, values = [0.0, 0.0, 2.0], [10, 20, 100]\nposition = 1\nmasked = [s if j <= position else -math.inf for j,s in enumerate(scores)]\nweights = [math.exp(s) for s in masked]\nweights = [w / sum(weights) for w in weights]\nprint("weights", weights)\nprint("output", sum(w*v for w,v in zip(weights, values)))',output:'weights [0.5, 0.5, 0.0]\noutput 15.0',explanation:'position=1 使用从 0 开始的编号，所以代表第二个位置。这个例子展示可见性和加权平均，不是在训练一个 Transformer。'},
 checks:[Q('把第三个 value 从 100 改为 10000，当前输出是多少？','先看第三个权重。','仍为 15，因为第三个位置的权重为 0。若你的实现变化了，需要排查遮挡。',2),Q('为什么把未来分数加 1 不能阻止读取它？','softmax 后只要权重不是 0，就仍会贡献内容。','加 1 通常还会增加它的相对权重；禁止位置需要被实际排除，而不是加一个有限的小数。',2)],
 practice:{title:'先做对，再故意破坏一次',steps:[A('运行示例，手算三个权重和输出。','权重总和为 1，未来位置权重为 0。','负无穷通过 math.exp 变为 0。'),A('把遮挡分支 -math.inf 改为 1.0。','未来位置重新获得非零权重，输出受到 100 的影响。','这是故意引入的信息泄漏，不是提高模型能力。'),A('完成因果 mask 代码练习。','能写清允许访问的位置，并处理补齐位置。','先画 3×3 可见性表，再写循环。')]},links:[{label:'因果可见性实验',href:'#/labs/attention'},{label:'实现因果掩码',href:'#/code/causal-mask'}],sources:[S.transformer,S.masks]
}),
L(2,3,{
 title:'语言模型怎样逐个生成：从训练对到 Transformer',summary:'用“我爱琴”解释下一单位预测，再把 Attention 放回完整网络，区分三类结构。',prerequisites:['w2-l1','w2-l2','w1-l2'],
 terms:[T('AR 自回归','用之前的内容来预测下一个内容，再不断重复。','生成一个字后，把它放回输入，预测下一个。'),T('teacher forcing 真实历史训练','训练时每个预测位置使用数据里的正确历史。','预测“琴”时输入的是正确的“我爱”，而不是模型刚刚猜出来的历史。'),T('Transformer','组合注意力、逐位置的前馈网络、残差连接与归一化等模块的网络结构。','Attention 是其中一种信息交流机制，不等于整个网络。'),T('Decoder-only','主要由带因果约束的生成模块堆叠而成的结构形式。','常把提示和待生成内容接成一个序列；名称本身不决定输出是文字还是视觉特征。')],
 sections:[P('第 1 步：构造一组不偷看答案的训练对','给“我爱琴”加开始符 BOS 和结束符 EOS。输入为 [BOS,我,爱,琴]，目标为 [我,爱,琴,EOS]。输入的第一个位置预测“我”，第二个位置在看到“我”后预测“爱”。','这里的右移关系常让人混淆。请逐行写“可见前缀 → 下一单位”，而不是只比较两个数组的长度。EOS 是约定的结束标记，不是普通标点。'),P('第 2 步：理解并行训练与顺序生成','训练时整句正确文本已经在数据里，所以可以一次计算所有位置的输出，但通过因果掩码确保每个位置只看自己的前缀。这就是使用真实历史的 teacher forcing。','生成时未来答案还不存在。先给 BOS，模型选择“我”；再给 [BOS,我]，选择“爱”。如果第一步选错，错误内容会进入后续条件。这就是自由运行，也称 free-running；要单独评价连续生成。'),P('第 3 步：一层网络还包含什么','Attention 让位置间交换信息。前馈网络通常对每个位置的向量做同一套非线性变换；残差连接把子模块输入加回输出，为信息和梯度提供直接路径；归一化调整数值尺度。这些操作组合成层，再重复多层。','本周不要求一次手写全部细节。先能画出“编号 → 嵌入 → 多层计算 → 候选词分数”的顺序。第 3 周会用一个小训练脚本检查这条路径怎样连接到损失和更新。'),P('第 4 步：用可见范围区分结构','Encoder-only 通常让输入位置彼此双向可见，常用于理解或提取表示。Encoder–Decoder 用编码器读取条件，再由解码器逐步生成目标。Decoder-only 常把条件和目标都放在一个因果序列里。','结构是怎样计算；AR 是怎样按历史组织预测。一个 Decoder-only 网络也可能预测连续的视觉向量。不要把结构名称等同于“只能做聊天”。'),P('第 5 步：区分预测分数与选择结果','网络会给每个候选 token 一个分数；下一课学习怎样把分数转成概率。选最大值叫贪心；按概率随机选叫采样。temperature 温度会调整选择分布的尖锐程度，top-p 会限制参与采样的候选集合。','在参数固定时改变采样设置，只改变如何使用模型输出，并没有重新训练。对比两个模型时，要记录相同的生成长度和选择规则，否则结果不可直接归因于训练。')],
 worked:{title:'把四个训练位置完整展开',steps:['BOS → 我。','BOS、我 → 爱。','BOS、我、爱 → 琴。','BOS、我、爱、琴 → EOS。每行只使用箭头左侧的信息。'],takeaway:'训练可以并行算这些行，生成却必须先得到前一行的输出。'},
 example:{code:'sequence = ["BOS", "我", "爱", "琴", "EOS"]\ninputs, targets = sequence[:-1], sequence[1:]\nfor i, target in enumerate(targets):\n    print(" ".join(inputs[:i+1]), "->", target)',output:'BOS -> 我\nBOS 我 -> 爱\nBOS 我 爱 -> 琴\nBOS 我 爱 琴 -> EOS',explanation:'这段代码是训练对的展开检查，不是已经训练好的生成器。箭头右边不能进入同一位置可见的输入。'},
 checks:[Q('第 3 个输入位置“爱”应该预测什么？','从展开后的第 3 行找答案。','预测“琴”。它可以看 BOS、我、爱，不能看到未来输入位置中的琴。',0),Q('模型权重不动，只改变 temperature，算不算训练？','寻找是否有根据损失更新参数的动作。','不算。这是推理时的选择策略变化，没有改变学到的权重。',4)],
 practice:{title:'从数据对检查到生成流程图',steps:[A('把句子改成“我学琴”，重新构造输入和目标。','四个训练位置都能写成合法前缀与下一单位。','输入、目标长度相等，但内容错开一位。'),A('画两条路径：真实历史训练、使用自身输出的生成。','清楚标出下一次输入来自数据还是来自模型。','不要把训练时并行计算误认为未来答案可见。'),A('给 Transformer 画一张五步框图。','编号、嵌入、注意力和前馈堆叠、输出分数、选择 token。','不要求在图中填所有实现细节；每个模块先写输入输出职责。')]},sources:[S.transformer,S.hf]
})];
